function count(value){return Array.isArray(value)?value.length:0;}
function clamp(value){return Math.max(0,Math.min(100,Math.round(value)));}
export function auditSkillDepth(skill){let score=0;const desc=String(skill?.identity?.description??'');if(/^Use when\b/.test(desc)&&desc.length>=70&&!/skill is required/i.test(desc))score+=15;score+=Math.min(15,count(skill?.identity?.antiTriggers)*7.5);score+=Math.min(15,count(skill?.procedure?.steps)*5);score+=Math.min(10,count(skill?.procedure?.fallbackPaths)*10);score+=Math.min(10,count(skill?.procedure?.stopConditions)*10);score+=Math.min(15,count(skill?.verification?.executableChecks)*7.5);score+=Math.min(10,count(skill?.verification?.evidenceTypes)*10);score+=Math.min(5,count(skill?.relations?.requires)*5);const target=Number(skill?.context?.targetTokens??Infinity),hard=Number(skill?.context?.hardTokens??Infinity);if(target<=1200&&hard<=1800&&target<=hard)score+=5;const result={score:clamp(score),dimensions:{triggerPrecision:score>=15,antiTriggerCoverage:count(skill?.identity?.antiTriggers),procedureSteps:count(skill?.procedure?.steps),fallbackPaths:count(skill?.procedure?.fallbackPaths),stopConditions:count(skill?.procedure?.stopConditions),executableChecks:count(skill?.verification?.executableChecks),evidenceTypes:count(skill?.verification?.evidenceTypes)}};return Object.freeze(result);}
export function auditBoilerplate(skills,{commonThreshold=.8}={}){const frequency=new Map();for(const skill of skills)for(const line of new Set((skill.lines??[]).map((value)=>String(value).trim()).filter(Boolean)))frequency.set(line,(frequency.get(line)??0)+1);const minimum=Math.ceil(skills.length*commonThreshold);const common=new Set([...frequency].filter(([,n])=>n>=minimum).map(([line])=>line));const reports=skills.map((skill)=>{const lines=(skill.lines??[]).map((value)=>String(value).trim()).filter(Boolean);const commonCount=lines.filter((line)=>common.has(line)).length;return{id:skill.id,lines:lines.length,commonLines:commonCount,boilerplateRatio:lines.length?commonCount/lines.length:0};});return Object.freeze({commonLines:[...common].sort(),skills:Object.freeze(reports)});}
